const lv_image_dsc_t *brand_logo(const char *brand)
{
    static const struct
    {
        const char *id;
        const lv_image_dsc_t *img;
    } MAP[] = {
        {"bambulab", &LOGO_BAMBULAB},
        {"creality", &LOGO_CREALITY},
        {"anycubic", &LOGO_ANYCUBIC},
        {"elegoo", &LOGO_ELEGOO},
        {"flashforge", &LOGO_FLASHFORGE},
        {"prusa", &LOGO_PRUSA},
        {"snapmaker", &LOGO_SNAPMAKER},
        {"klipper", &LOGO_KLIPPER},
        {"octoprint", &LOGO_OCTOPRINT},
    };
    for (size_t i = 0; brand && i < sizeof MAP / sizeof MAP[0]; i++)
    {
        if (strcmp(MAP[i].id, brand) == 0)
        {
            return MAP[i].img;
        }
    }
    return NULL;
}
